import { z } from "zod";

export const Order = z.object({
  id: z.string().regex(/^[0-9]+$/),      // ids as strings: JSON numbers lose precision
  sku: z.string(),
  qty: z.number().int().nonnegative(),
});
export type Order = z.infer<typeof Order>;

const order = Order.parse(JSON.parse(body));   // contract enforced at the boundary
